"""BIEK Computer Science 12th Class Past Paper Trend Analysis Report Generator"""

import pandas as pd
import matplotlib.pyplot as plt
import matplotlib
matplotlib.use('Agg')
import base64
from io import BytesIO
from collections import Counter
import re
import json

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# Data overview
total_questions = len(df)
years = sorted(df['year'].unique())
question_types = df['type'].unique()

# Year-by-year stats
yearly_counts = df.groupby('year').size().reset_index(name='total')
type_yearly = df.groupby(['year', 'type']).size().unstack(fill_value=0)
type_yearly_pct = type_yearly.div(type_yearly.sum(axis=1), axis=0) * 100

# Question type overall
type_counts = df['type'].value_counts()

# YoY change
yearly_counts['prev_total'] = yearly_counts['total'].shift(1)
yearly_counts['yoy_change'] = yearly_counts['total'] - yearly_counts['prev_total']
yearly_counts['yoy_pct'] = (yearly_counts['yoy_change'] / yearly_counts['prev_total'] * 100).round(1)

# Average per type
avg_by_type = type_yearly.mean()

# Keyword extraction
def clean_text(text):
    if pd.isna(text):
        return ""
    text = str(text)
    text = text.replace('$', ' ')
    text = re.sub(r'[^a-zA-Z\s]', ' ', text)
    text = text.lower()
    return text

df['clean_question'] = df['question'].apply(clean_text)

# Topic keywords for analysis
topics = {
    'C Programming': ['function', 'loop', 'printf', 'scanf', 'variable', 'operator', 'data type', 'array', 'string', 'recursion', 'pointer', 'structure', 'file', 'switch', 'while', 'for', 'do-while', 'break', 'continue', 'return', 'main'],
