# Keyword extraction
def clean_text(text):
    if pd.isna(text):
        return ""
    text = str(text)
    text = text.replace('$', ' ')
    text = re.sub(r'[^a-zA-Z\s]', ' ', text)
    text = text.lower()
    return text

